B.5 Demo: Dates
Demonstration used in Section 5.2, this time with the object-oriented DateTime class, instead of the date() function.
&lt;?php
// Create and show the current date and time
$currentDate = new DateTime();
echo "&lt;p&gt;Current date and time: " . $currentDate-&gt;format('d-m-Y H:i:s') . "&lt;/p&gt;";

// Add days to a date (clone so as not to change the original object)
$futureDate = clone $currentDate;
$futureDate-&gt;modify('+150 days');
echo "&lt;p&gt;Date in 150 days: " . $futureDate-&gt;format('Y-m-d') . "&lt;/p&gt;";

// Subtract days from a date
$pastDate = clone $currentDate;
$pastDate-&gt;modify('-10 days');
echo "&lt;p&gt;Date 10 days ago: " . $pastDate-&gt;format('Y-m-d') . "&lt;/p&gt;";

// Difference between two dates
$interval = $currentDate-&gt;diff($pastDate);
echo "&lt;p&gt;Difference: " . $interval-&gt;days . " days&lt;/p&gt;";

// Create a date from a string, in a specific format
$specificDate = DateTime::createFromFormat('Y-m-d', '2024-12-25');
echo "&lt;p&gt;Specific date (Christmas): " . $specificDate-&gt;format('Y-m-d') . "&lt;/p&gt;";

// Check whether a year is a leap year
$year = (int) $specificDate-&gt;format('Y');
if ($year % 4 === 0 && ($year % 100 !== 0 || $year % 400 === 0)) {
    echo "&lt;p&gt;$year is a leap year.&lt;/p&gt;";
} else {
    echo "&lt;p&gt;$year is not a leap year.&lt;/p&gt;";
}

